package dev.utherhel.attributification.mixin;

import dev.utherhel.attributification.selftest.SelfTest;
import java.util.function.BooleanSupplier;
import net.minecraft.server.MinecraftServer;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/** Drives the dev self-test from the server tick; inert unless -Dattributification.selftest is set. Generated by dev/modtest/sync.py. */
@Mixin(MinecraftServer.class)
public abstract class SelfTestServerMixin {
    @Inject(method = "tickServer", at = @At("TAIL"))
    private void attributification$modtestTick(BooleanSupplier hasTimeLeft, CallbackInfo ci) {
        if (SelfTest.active()) SelfTest.onServerTick((MinecraftServer) (Object) this);
    }
}
